import {readFileSync} from 'node:fs';
import {id,canonical} from '../../../lib/credit-engine/recommendations/common.ts';
// Independently authored methodology intent. Never derive these expectations
// from Recommendation Engine output. Synthetic canonical facts only.
import {scenario,baseline,defect,portfolio,reverseSets} from './builders.mjs';
const req=(code,fields={},extra={})=>({code,fields,...extra});
export function buildRecommendationEntries(){const cs=[];const add=(description,input,required=[],extra={})=>{cs.push({caseId:'REC-RU-'+String(cs.length+1).padStart(3,'0'),description,synthetic:true,reviewStatus:'GOLDEN',input,expectations:{required:required.map(v=>typeof v==='string'?req(v):v),maximumPrimary:10,...extra}});};
add('Отрицательный капитал: сверка и документированная поддержка',scenario({values:{FIN_EQUITY:-100}}),['RECONCILE_EQUITY_COMPONENTS','ASSESS_CAPITAL_SUPPORT']);
add('Известный нулевой капитал',scenario({values:{FIN_EQUITY:0}}),['RECONCILE_EQUITY_COMPONENTS']);
add('Reported отрицательные чистые активы',scenario({values:{FIN_REPORTED_NET_ASSETS:-100}}),['VERIFY_REPORTED_NET_ASSETS']);
add('Прокси не становится reported net assets',scenario({values:{FIN_REPORTED_NET_ASSETS:null,FIN_NET_ASSETS_PROXY:-100}}),[req('OBTAIN_REPORTED_NET_ASSETS',{actionability:'VERIFY_FIRST'})],{forbidden:['VERIFY_REPORTED_NET_ASSETS']});
add('Низкая текущая ликвидность',scenario({values:{FIN_CURRENT_RATIO:.7}}),['BUILD_RECEIVABLES_AGING','MAP_SHORT_LIABILITY_DATES']);
add('Отрицательный оборотный капитал',scenario({values:{FIN_WORKING_CAPITAL:-100}}),['RECONCILE_WORKING_CAPITAL']);
add('Материальный дефицит оборотного капитала',scenario({values:{FIN_WORKING_CAPITAL:-500,FIN_CURRENT_ASSETS:1000}}),['NEGOTIATE_PAYABLE_TERMS','COLLECT_MATURE_RECEIVABLES']);
add('Годовой убыток: расшифровка результата',scenario({values:{FIN_ANNUAL_NET_PROFIT:-100}}),['EXPLAIN_CURRENT_LOSS']);
add('Повторяющиеся убытки подавляют повтор общей расшифровки',scenario({values:{FIN_ANNUAL_NET_PROFIT:-100,FIN_CONSECUTIVE_ANNUAL_LOSSES:2}}),['ANALYZE_REPEATED_LOSSES'],{forbidden:['EXPLAIN_CURRENT_LOSS'],suppressed:['EXPLAIN_CURRENT_LOSS']});
add('Среднее снижение годовой выручки',scenario({values:{FIN_ANNUAL_REVENUE_CHANGE:-15}}),['BRIDGE_ANNUAL_REVENUE']);
add('Высокое снижение выручки',scenario({values:{FIN_ANNUAL_REVENUE_CHANGE:-30}}),[req('BRIDGE_ANNUAL_REVENUE',{priority:'P1_HIGH'})]);
add('Недостаточное покрытие процентов',scenario({values:{FIN_INTEREST_COVERAGE:.5}}),['RECONCILE_INTEREST_EXPENSE']);
add('Средняя нагрузка обслуживания',scenario({values:{BANK_DEBT_SERVICE_RATIO:.3,BANK_COVERAGE_ADEQUATE:true}}),['RECONCILE_DEBT_SERVICE_COMPONENTS']);
add('Высокая нагрузка обслуживания',scenario({values:{BANK_DEBT_SERVICE_RATIO:.6,BANK_COVERAGE_ADEQUATE:true}}),['ALIGN_DEBT_SERVICE_RECEIPTS']);
add('Снижение операционных поступлений',scenario({values:{BANK_OPERATING_TREND:-40,BANK_COVERAGE_ADEQUATE:true}}),['EXPLAIN_OPERATING_RECEIPTS']);
add('Прямая концентрация без договорного контекста',scenario({values:{BANK_TOP1:.8,BANK_IDENTITY_COVERAGE:1,BANK_CONCENTRATION_COVERAGE:1}}),['QUANTIFY_CUSTOMER_DEPENDENCY','DEVELOP_CUSTOMER_PIPELINE'],{forbidden:['DOCUMENT_CONCENTRATION_CONTRACT']});
add('Концентрация с действующим договором',scenario({contract:true,values:{BANK_IDENTITY_COVERAGE:1,BANK_CONCENTRATION_COVERAGE:1}}),['DOCUMENT_CONCENTRATION_CONTRACT','MONITOR_CONTRACT_RECEIPTS'],{forbidden:['DEVELOP_CUSTOMER_PIPELINE']});
add('Площадка не становится прямым клиентом',scenario({marketplace:true}),[],{forbidden:['DEVELOP_CUSTOMER_PIPELINE','QUANTIFY_CUSTOMER_DEPENDENCY']});
add('Неясные поступления: первичное основание',scenario({values:{BANK_UNKNOWN_INFLOW_SHARE:.8}}),['EXPLAIN_UNKNOWN_INFLOWS']);
add('Наличные и физические лица: прослеживаемость',scenario({values:{BANK_UNCLEAR_CASH_SHARE:.8}}),['DOCUMENT_CASH_ORIGIN','DOCUMENT_INDIVIDUAL_TRANSFERS']);
add('Ошибка реконструкции остатков',scenario({values:{BANK_NEGATIVE_RECONSTRUCTED_DAYS:10}}),['RECONCILE_BANK_ANCHORS']);
add('Низкие остатки: документированный разрыв',scenario({values:{BANK_LOW_LIQUIDITY_SHARE:.8,BANK_COVERAGE_ADEQUATE:true}}),['MAP_CONFIRMED_LIQUIDITY_GAPS']);
add('Выручка и поступления остаются разными понятиями',scenario({values:{FIN_ANNUAL_REVENUE_CHANGE:-30,BANK_OPERATING_TREND:-40,BANK_COVERAGE_ADEQUATE:true}}),['BRIDGE_ANNUAL_REVENUE','RECONCILE_RECEIPTS_WITH_REVENUE']);
add('LOW evidence не становится операционным предписанием',scenario({values:{BANK_OPERATING_TREND:-40,BANK_COVERAGE_ADEQUATE:true},lowFinding:'RISK-CF-OPERATING-RECEIPTS-DECLINE'}),[req('EXPLAIN_OPERATING_RECEIPTS',{actionability:'VERIFY_FIRST'})]);
add('Подтвержденная текущая просрочка: урегулирование',scenario({values:{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0}}),[req('SETTLE_VALID_CURRENT_OVERDUE',{actionability:'ACTIONABLE'},{prerequisite:'VERIFY_CURRENT_OVERDUE_BALANCE'})]);
add('Неидентифицированная просрочка: сначала проверка',scenario({values:{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0},noIdentity:true}),[req('VERIFY_CURRENT_OVERDUE_BALANCE',{actionability:'VERIFY_FIRST'}),'RECONCILE_CREDITOR_CONTRACT'],{forbidden:['SETTLE_VALID_CURRENT_OVERDUE']});
for(const days of [10,40,60])add('Достоверная историческая просрочка '+days+' дней неизменяема',scenario({values:{BKI_OVERDUE:0,BKI_HISTORY_DAYS:days}}),[req('VERIFY_HISTORICAL_DELINQUENCY',{remediability:'NOT_REMOVABLE'})]);
add('Текущая просрочка при историческом максимуме ноль',scenario({values:{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0}}),['VERIFY_CURRENT_OVERDUE_BALANCE'],{forbidden:['VERIFY_HISTORICAL_DELINQUENCY','MONITOR_SERVICING_AFTER_DELINQUENCY']});
add('Та же просрочка не создает дублирующую историческую ремедиацию',scenario({values:{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:60}}),['VERIFY_CURRENT_OVERDUE_BALANCE'],{forbidden:['VERIFY_HISTORICAL_DELINQUENCY']});
add('Нулевой запас обслуживания',scenario({debt:1000000}),['VERIFY_ZERO_HEADROOM_SERVICE','ASSESS_SERVICE_RESTRUCTURING']);
add('Частичная capacity требует подтверждений',scenario({monthCount:6}),['COMPLETE_CAPACITY_EVIDENCE']);
add('Недостаточная история capacity',scenario({monthCount:2}),['RESTORE_CAPACITY_INPUTS']);
const pf=portfolio(),pid=pf.obligations[0].obligationId;
for(const [n,code,label] of [['PORTFOLIO_UNRESOLVED','IDENTIFY_PORTFOLIO_OBLIGATION','Неразрешенная идентичность'],['PORTFOLIO_UNKNOWN_FUNDED','CONFIRM_PORTFOLIO_OUTSTANDING','Неизвестный остаток'],['PORTFOLIO_CONFLICTS','RECONCILE_PORTFOLIO_CONFLICT','Конфликт остатка'],['PORTFOLIO_NEW','CONFIRM_NEW_OBLIGATION_TERMS','Новое обязательство'],['PORTFOLIO_UNMATCHED','LINK_UNMATCHED_DEBT_PAYMENT','Несопоставленный платеж'],['PORTFOLIO_UNSPLIT','SPLIT_REPORTED_DEBT_SERVICE','Неразделенный платеж']])add(label,scenario({creditPortfolio:pf,values:{[n]:1}}),[req(code,{}, {obligationId:pid})]);
add('Ближайший известный платеж',scenario({creditPortfolio:pf}),['VERIFY_NEAR_PAYMENT_SCHEDULE']);
add('Гарантия остается условной',scenario({creditPortfolio:portfolio({type:'BANK_GUARANTEE'})}),['CONFIRM_GUARANTEE_EXPIRY']);
add('Поручительство отдельно от собственного кредита',scenario({creditPortfolio:portfolio({type:'GUARANTORSHIP'})}),['CONFIRM_GUARANTORSHIP_SCOPE']);
add('Закрытое обязательство не требует текущего платежа',scenario({creditPortfolio:portfolio({status:'CLOSED'})}),[],{forbidden:['VERIFY_NEAR_PAYMENT_SCHEDULE']});
for(const [state,code,label] of [['TERMINATED','VERIFY_ENTITY_TERMINATION','Прекращение компании'],['LIQUIDATION','VERIFY_LIQUIDATION_STAGE','Ликвидация'],['BANKRUPTCY_ACTIVE','VERIFY_BANKRUPTCY_PROCEDURE','Банкротство']])add(label,scenario({values:{LEGAL_LIFECYCLE:state,FIN_EQUITY:-100}}),[code],{status:'NOT_RATABLE_GLOBAL_STOP',forbidden:['ASSESS_CAPITAL_SUPPORT']});
add('Недостоверный адрес',scenario({values:{LEGAL_ADDRESS_UNRELIABLE:true}}),['VERIFY_REGISTERED_ADDRESS']);
add('Существенное исполнительное производство',scenario({values:{LEGAL_ACTIVE_ENFORCEMENT_AMOUNT:1000000,LEGAL_ENFORCEMENT_REVENUE_RATIO:.1}}),['RECONCILE_ENFORCEMENT_BALANCE']);
add('Информационный уровень исполнения',scenario({values:{LEGAL_ACTIVE_ENFORCEMENT_AMOUNT:1000,LEGAL_ENFORCEMENT_REVENUE_RATIO:null}}),[req('RECONCILE_ENFORCEMENT_BALANCE',{priority:'P3_LOW'})]);
add('Судебный спор не равен доказанному долгу',scenario({values:{LEGAL_DEFENDANT_CASES:1}}),['DOCUMENT_LITIGATION_STAGE']);
add('Сообщение о банкротстве требует проверки контекста',scenario({values:{LEGAL_REGISTRY_REVIEW:1}}),['VERIFY_BANKRUPTCY_MESSAGE_CONTEXT']);
add('Проверка и исполнение предписаний',scenario({values:{LEGAL_VIOLATIONS_REPORTED:1}}),['DOCUMENT_INSPECTION_OUTCOME']);
add('Конфликт компании P0',scenario({values:{RECON_IDENTITY_CONFLICTS:1}}),[req('RECONCILE_COMPANY_IDENTITY',{priority:'P0_CRITICAL'})]);
add('Конфликт одного финансового факта',scenario({values:{RECON_SAME_FACT_CONFLICTS:1}}),['RECONCILE_SAME_FINANCIAL_FACT']);
add('Межисточниковая проверка',scenario({values:{RECON_OTHER_REVIEW:1}}),['EXPLAIN_CROSS_SOURCE_DIFFERENCE']);
add('Отсутствующий источник',scenario({values:{SOURCE_MISSING_COUNT:1}}),['OBTAIN_MISSING_SOURCE']);
add('Устаревший источник',scenario({values:{SOURCE_STALE_COUNT:1}}),['REFRESH_STALE_SOURCE']);
add('Неуспешный источник',scenario({values:{SOURCE_FAILED_COUNT:1}}),['REPLACE_UNREADABLE_SOURCE']);
add('Отсутствующий месяц',scenario({values:{BANK_COVERAGE_ISSUE:2}}),['UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD']);
add('Неполный месяц',scenario({values:{BANK_COVERAGE_ISSUE:1}}),['UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD']);
add('Перекрытие выписок',scenario({values:{BANK_COVERAGE_ISSUE:3}}),['RECONCILE_OVERLAPPING_STATEMENTS']);
add('Низкая целостность источника',scenario({values:{INTEGRITY_CONFIDENCE:30}}),['VERIFY_LOW_INTEGRITY_SOURCE']);
add('Несколько оснований одного комплекта выписок',scenario({sourceId:'synthetic-bank',values:{SOURCE_MISSING_COUNT:1,BANK_COVERAGE_ISSUE:2}}),['UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD'],{exactCodeCount:{UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD:1}});
add('Не определена цель',scenario({caseValues:{financingPurpose:null}}),['DEFINE_FINANCING_PURPOSE']);
add('Не определена сумма',scenario({caseValues:{requestedAmount:null}}),['DEFINE_REQUESTED_AMOUNT']);
add('Не определен срок',scenario({caseValues:{requestedTermMonths:null}}),['DEFINE_REQUESTED_TERM']);
add('Не определено предпочтение продукта',scenario({caseValues:{requestedProduct:null}}),['DEFINE_REQUESTED_PRODUCT']);
add('Контрактная цель без договора',scenario({caseValues:{financingPurpose:'CONTRACT_EXECUTION',requestedProduct:'BANK_GUARANTEE',contractReference:null}}),['LINK_CASE_CONTRACT','PREPARE_GUARANTEE_CONTRACT']);
add('Факторинг без реестра требований',scenario({caseValues:{requestedProduct:'FACTORING'}}),['PREPARE_FACTORING_RECEIVABLES']);
add('Лизинг без спецификации',scenario({caseValues:{financingPurpose:'EQUIPMENT',requestedProduct:'LEASING'}}),['PREPARE_LEASE_ASSET_SPEC']);
add('Денежный продукт при неизвестной capacity',scenario({monthCount:2}),['COMPLETE_FUNDED_SERVICE_EVIDENCE']);
add('Срочный кредит без явного сценария',scenario({caseValues:{requestedProduct:'TERM_LOAN'}}),['DEFINE_RATE_TERM_SCENARIO']);
add('Запрошенный продукт расходится с целью',scenario({caseValues:{financingPurpose:'EQUIPMENT',requestedProduct:'FACTORING'}}),['CLARIFY_PRODUCT_PURPOSE_MISMATCH']);
add('Низкий Index сам не создает действия',baseline({indexValue:600}),[],{forbidden:['SETTLE_VALID_CURRENT_OVERDUE','ASSESS_CAPITAL_SUPPORT']});
add('Высокий Index не означает подать заявку',baseline({indexValue:900}),[],{forbidden:['SETTLE_VALID_CURRENT_OVERDUE','ASSESS_CAPITAL_SUPPORT']});
add('Заявление клиента не становится доказательством',scenario({caseValues:{contractReference:'CLIENT-ONLY'}}),[req('SUPPORT_CLIENT_DECLARATION',{actionability:'VERIFY_FIRST'})]);
add('Перестановка входных наборов',reverseSets(scenario({values:{FIN_EQUITY:-100}})),['RECONCILE_EQUITY_COMPONENTS']);
add('Реалистичный набор нескольких рисков',scenario({values:{FIN_EQUITY:-100,FIN_ANNUAL_NET_PROFIT:-100,BANK_OPERATING_TREND:-40,BANK_COVERAGE_ADEQUATE:true,BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0}}),['RECONCILE_EQUITY_COMPONENTS','EXPLAIN_CURRENT_LOSS','EXPLAIN_OPERATING_RECEIPTS','SETTLE_VALID_CURRENT_OVERDUE']);
add('Полный набор сохранен при десяти первичных',scenario({values:{FIN_EQUITY:-100,FIN_ANNUAL_NET_PROFIT:-100,FIN_CURRENT_RATIO:.5,FIN_WORKING_CAPITAL:-100,BANK_OPERATING_TREND:-40,BANK_COVERAGE_ADEQUATE:true,BANK_UNKNOWN_INFLOW_SHARE:.8,BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0}}),['RECONCILE_EQUITY_COMPONENTS'],{minimumRecommendations:20});
if(cs.length!==80)throw Error('Original Golden count must be 80, got '+cs.length);
cs.push({caseId:'REC-RU-DEFECT-001',description:'Постоянная цепочка regression: overdue >0, historical max =0 KNOWN, без выдуманных диапазонов дней',synthetic:true,reviewStatus:'GOLDEN',input:defect(),expectations:{required:[req('VERIFY_CURRENT_OVERDUE_BALANCE',{}, {sourceFindingCode:'RISK-BKI-CURRENT-OVERDUE'})],forbidden:['VERIFY_HISTORICAL_DELINQUENCY','MONITOR_SERVICING_AFTER_DELINQUENCY'],maximumPrimary:10}});
return cs;}

export function loadRecommendationPack(){const cs=buildRecommendationEntries(),hashes=JSON.parse(readFileSync(new URL('./fingerprints-stage5.json',import.meta.url),'utf8'));for(const c of cs)if(hashes[c.caseId]!==id('recommendation-golden',canonical(c)))throw Error('RECOMMENDATION_GOLDEN_FINGERPRINT_MISMATCH:'+c.caseId);return cs;}
